def _primes_lt(n):
    s = bytearray(b'\x01') * n
    s[0:2] = b'\x00\x00'
    import math as _m
    for i in range(2, int(_m.isqrt(n)) + 1):
        if s[i]:
            s[i*i:n:i] = b'\x00' * ((n - 1 - i*i)//i + 1)
    return [i for i in range(n) if s[i]]

_SMALL_PRIMES = _primes_lt(1000)
_PROD = 1
for _p in _SMALL_PRIMES:
    _PROD *= _p
_SMALL_SET = frozenset(_SMALL_PRIMES)

def is_primes(ns):
    """For each int n below 10**12, True if n is prime, else False.
    Negative numbers, 0 and 1 are not prime."""
    out = []
    ap = out.append
    PROD = _PROD
    SSET = _SMALL_SET
    for n in ns:
        if n < 1000:
            # direct lookup (covers negatives, 0, 1, small)
            ap(n in SSET)
            continue
        if (n & 1) == 0:
            ap(False)
            continue
        # fast small-factor rejection: single C-level gcd vs primorial
        if math.gcd(n, PROD) != 1:
            ap(False)
            continue
        # Miller-Rabin, deterministic for n < 1e12 (< 2152302898747 -> bases 2,3,5,7,11)
        d = n - 1
        s = 0
        while (d & 1) == 0:
            d >>= 1
            s += 1
        nm1 = n - 1
        if n < 4759123141:
            # deterministic for n < 4759123141
            bases = (2, 7, 61)
        else:
            bases = (2, 3, 5, 7, 11)
        is_p = True
        for a in bases:
            x = pow(a, d, n)
            if x == 1 or x == nm1:
                continue
            for _ in range(s - 1):
                x = (x * x) % n
                if x == nm1:
                    break
            else:
                is_p = False
                break
        ap(is_p)
    return out
